// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _check(address u, uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        u = address(this);
        vm.assume(address(this).balance >= v);
        try c.addToBalance{value: v}() {} catch { return; }
        assertTrue(c.getBalance(u) == v);
    }

    function testFuzz_check(address u, uint256 v) public {
        _check(u, v);
    }

    receive() external payable {}

    fallback() external payable {}
}
